macro_rules! deps {
    () => {
        FromRadix10Signed!();
    };
}

macro_rules! FromRadix10SignedChecked {
    () => {
        deps!();
        # [doc = " Types implementing this trait can be parsed from a positional numeral system with radix 10."] # [doc = " Acts much like `FromRadix10Signed`, but performs additional checks for overflows."] pub trait FromRadix10SignedChecked : FromRadix10Signed { # [doc = " Parses an integer from a slice."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use atoi::FromRadix10SignedChecked;"] # [doc = " // Parsing to digits from a slice"] # [doc = " assert_eq!((Some(42),2), u32::from_radix_10_signed_checked(b\"42\"));"] # [doc = " // Additional bytes after the number are ignored"] # [doc = " assert_eq!((Some(42),2), u32::from_radix_10_signed_checked(b\"42 is the answer to life, the universe and everything\"));"] # [doc = " // (0,0) is returned if the slice does not start with a digit"] # [doc = " assert_eq!((Some(0),0), u32::from_radix_10_signed_checked(b\"Sadly we do not know the question\"));"] # [doc = " // While signed integer types are supported..."] # [doc = " assert_eq!((Some(42),2), i32::from_radix_10_signed_checked(b\"42\"));"] # [doc = " // Signs are allowed"] # [doc = " assert_eq!((Some(-42),3), i32::from_radix_10_signed_checked(b\"-42\"));"] # [doc = " // -0 is ok, even for an unsigned type"] # [doc = " assert_eq!((Some(0),2), u32::from_radix_10_signed_checked(b\"-0\"));"] # [doc = " // -1 is an Underflow"] # [doc = " assert_eq!((None,2), u32::from_radix_10_signed_checked(b\"-1\"));"] # [doc = " // Negative values for unsigned types are handled as `None`."] # [doc = " assert_eq!((None,3), u32::from_radix_10_signed_checked(b\"-42\"));"] # [doc = " // Leading zeros are allowed"] # [doc = " assert_eq!((Some(42),4), u32::from_radix_10_signed_checked(b\"0042\"));"] # [doc = " // Overflow is indicated by `None`"] # [doc = " assert_eq!((None, 3), u8::from_radix_10_signed_checked(b\"256\"));"] # [doc = " assert_eq!((None, 4), i8::from_radix_10_signed_checked(b\"+128\"));"] # [doc = " assert_eq!((None, 4), i8::from_radix_10_signed_checked(b\"-129\"));"] # [doc = " ```"] # [doc = ""] # [doc = " # Return"] # [doc = ""] # [doc = " Returns a tuple with two numbers. The first is the integer parsed or zero if no digit has"] # [doc = " been found. None, if there were too many, or too high dighits and the parsing overflowed."] # [doc = " The second is the index of the byte right after the parsed number. If the second element is"] # [doc = " zero the slice did not start with an ASCII digit."] fn from_radix_10_signed_checked (_ : & [u8]) -> (Option < Self > , usize) ; }
    };
}

FromRadix10SignedChecked!()